<?php use App\Core\Auth; ?><section class="panel"><div class="section-heading"><div><h2>Boarding assignments</h2><p>Hostels, rooms and beds are configured in Academic setup.</p></div><?php if(Auth::can('academics.manage')): ?><a class="button" href="<?= e(url('academics',['table'=>'hostels'])) ?>">Configure hostels</a><?php endif ?></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Hostel</th><th>Room / bed</th><th>Meals</th><th>Start</th><th>End</th><th>Status</th></tr></thead><tbody><?php if(!$rows) emptyRow(7); foreach($rows as $r): ?><tr><td><?= e($r['first_name'].' '.$r['last_name']) ?><small><?= e($r['admission_number']) ?></small></td><td><?= e($r['hostel_name']) ?></td><td><?= e($r['room_name'].' / '.$r['bed_name']) ?></td><td><?= e($r['meals']) ?></td><td><?= e($r['starts_on']) ?></td><td><?= e($r['ends_on']??'—') ?></td><td><?php badge($r['is_current']?'Active':'Previous'); ?></td></tr><?php endforeach ?></tbody></table></div></section><?php if(Auth::can('students.write')): ?><section class="panel"><h2>Assign or release a bed</h2><p class="muted">Only a student enrolled in a boarding type can receive an assignment. An occupied bed cannot be assigned twice.</p><?php startForm('boarding.save'); selectField('student_id','Student','students'); $beds=App\Core\DB::all("SELECT b.id,CONCAT(h.name,' / ',r.name,' / ',b.name) name FROM beds b JOIN rooms r ON r.school_id=b.school_id AND r.id=b.room_id JOIN hostels h ON h.school_id=r.school_id AND h.id=r.hostel_id WHERE b.school_id=?",[Auth::schoolId()]); selectField('bed_id','Bed',$beds,'',false); field('starts_on','Effective date','date',date('Y-m-d')); field('meals','Meals information','text','',false); ?><label class="check"><input type="checkbox" name="release" value="1"> Release current bed without assigning a new one</label><?php endForm('Save assignment'); ?></section><?php endif ?>
